def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        base = 18.0 if hp > 3 else 42.0
        return max(0.0, min(budget, base))

    total_req = WATER_REQ
    for _, opp in alive:
        total_req += opp.get('water_requirement', WATER_REQ)

    scarcity = supply / float(total_req) if total_req > 0 else 1.0

    prev_bids = []
    dangerous_prev = 0.0
    cindy_prev = None
    desperate_count = 0
    rich_count = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(float(pbid))
            if float(pbid) > dangerous_prev:
                dangerous_prev = float(pbid)
        if oid == 'Cindy' and pbid is not None:
            cindy_prev = float(pbid)
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
            desperate_count += 1
        if opp.get('budget', 0) >= 500:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if scarcity < 0.34:
        urgency += 2
    elif scarcity < 0.5:
        urgency += 1

    if desperate_count >= 2:
        urgency += 1

    if cindy_prev is not None and cindy_prev >= 110 and hp > 4 and no_water == 0 and scarcity < 0.45:
        return max(0.0, min(budget, 8.0))

    if urgency <= 1:
        bid = 14.0
        if scarcity > 0.42:
            bid = 10.0
        if highest_prev <= 20:
            bid = max(bid, highest_prev + 1.0)
    elif urgency == 2:
        bid = max(26.0, avg_prev + 3.0)
        if highest_prev > 80:
            bid = 38.0
    elif urgency == 3:
        bid = max(42.0, highest_prev + 2.0)
        if cindy_prev is not None and cindy_prev >= 120 and hp > 3:
            bid = 46.0
    elif urgency == 4:
        bid = max(58.0, highest_prev + 3.0)
        if rich_count >= 1:
            bid += 4.0
    else:
        bid = max(74.0, highest_prev + 5.0)
        if cindy_prev is not None and cindy_prev >= 120:
            bid = max(bid, 88.0)

    if day >= 8 and hp > 4 and budget < 140:
        bid *= 0.8

    if budget < DAILY_SALARY:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget, 0.95 * DAILY_SALARY + max(0, no_water - 1) * 8.0)

    if hp <= 2 or no_water >= 2:
        bid = min(budget, max(bid, 63.0))

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 # From meta-round state

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    current_day = day_context['day']
    days_remaining = EPISODE_DAYS - current_day

    # If no opponents are alive, bid conservatively to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Collect yesterday's bids from active opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Determine bid strategy based on my status and opponent behavior

    # Critical HP (will die if no water) or very late in the game, must secure water
    if my_status['hp'] <= WATER_REQ or days_remaining <= 1:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # If HP is moderately low, or it's the second to last day, bid high
    if my_status['hp'] <= WATER_REQ + 5 or days_remaining <= 2:
        if highest_prev_bid > DAILY_SALARY * 0.7:
            return min(my_status['budget'], highest_prev_bid + 5)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.8)

    # General bidding strategy, reacting to opponent's highest previous bid
    if highest_prev_bid >= DAILY_SALARY * 0.8:
        if my_status['hp'] > WATER_REQ + 5:
            return min(my_status['budget'], DAILY_SALARY * 0.4)
        else:
            return min(my_status['budget'], highest_prev_bid + 2)

    elif highest_prev_bid > DAILY_SALARY * 0.5:
        return min(my_status['budget'], highest_prev_bid + 1.5)

    else: # Opponents bid low or no previous bids, consider supply
        supply = day_context['supply']
        total_opp_water_needed = sum(o['water_requirement'] for o in alive_opponents)

        if supply >= WATER_REQ + total_opp_water_needed:
            return min(my_status['budget'], DAILY_SALARY * 0.2)
        elif supply >= WATER_REQ:
            return min(my_status['budget'], DAILY_SALARY * 0.5)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.7)

    return min(my_status['budget'], DAILY_SALARY * 0.5)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        bid = DAILY_SALARY * 0.6
    else:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        max_bid = max(yesterday_bids)
        if supply < 18:
            bid = min(my_status['budget'], max_bid * 1.1)
        else:
            bid = min(my_status['budget'], max(avg_bid * 0.95, DAILY_SALARY * 0.5))

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], max(bid, DAILY_SALARY * 0.95))

    return float(max(0, bid))
